# Lesson 4 of MKTG90037: competitive advantage (Week 2, first half): marketing's eras, core competence (VRIN), Porter's value
# chain, generic strategies, Ansoff, value disciplines. Brands: Hilton (10-K) and Coles (FY26). Instruments: which resources are
# core competences (Tag), Coles on the value chain (Place), which framework answers which question (Place).
from mk import *  # noqa: F403


def L04(CID):
    SK = 'mk.advantage'
    cats = [dict(id='core', label=T('Core competence: valuable, rare, hard to copy, hard to replace', '核心能力：有价值、稀缺、难模仿、难替代')), dict(id='copy', label=T('Easy to copy or buy', '容易被模仿或买到'))]
    items = [
        dict(text=T('A loyalty programme of 243 million members, built up over many years (Hilton Honors)', '一个积累多年、有 2.43 亿会员的忠诚计划（Hilton Honors）'), cat='core',
             why=T('Valuable, rare and slow to copy: a rival can launch a programme, not 243 million members.', '有价值、稀缺、难以很快复制：对手能推出一个计划，却推不出 2.43 亿会员。')),
        dict(text=T('A fresh colour scheme in the hotel lobby', '酒店大堂换一套新配色'), cat='copy', why=T('Visible and cheap to copy within months.', '看得见，几个月就能便宜地模仿。')),
        dict(text=T('Working relationships with more than 8,000 suppliers and over 1,800 outlets (Coles)', '与 8,000 多家供应商的合作关系，以及 1,800 多个门店（Coles）'), cat='core',
             why=T('Such a network is valuable and takes years to build; a new entrant cannot buy it.', '这样的网络有价值，要多年才建得起来；新进入者买不到。')),
        dict(text=T('A same-day delivery feature that any chain can license from an app provider', '任何连锁店都能向应用供应商买到的当日送达功能'), cat='copy',
             why=T('If it can be bought, it is a resource, not a competence. The competence is running the fulfilment network behind it.', '能买到的是资源，不是能力。能力是在它背后运营履约网络。')),
        dict(text=T('A temporary price cut on a popular product', '给热门商品临时降价'), cat='copy', why=T('The quickest thing to copy there is.', '这是最容易被模仿的东西。')),
        dict(text=T('A system and culture for running hotels owned by others to one standard, in many countries', '一套让他人拥有的酒店在多国按同一标准运营的体系和文化'), cat='core',
             why=T('A bundle of skills across teams, not one asset: hard to see, hard to copy (this is the course’s reading).', '是跨团队技能的组合，而不是单个资产：难看清、难模仿（这是本课程的解读）。')),
    ]
    chain_zones = [dict(id='in', label=T('Inbound logistics', '进货物流')), dict(id='ops', label=T('Operations', '运营')), dict(id='out', label=T('Outbound logistics', '出货物流')),
                   dict(id='mkt', label=T('Marketing and sales', '营销与销售')), dict(id='svc', label=T('Service', '服务')), dict(id='sup', label=T('Support activities (HR, technology, procurement, infrastructure)', '支持活动（人力、技术、采购、基础设施）'))]
    chain_chips = [
        dict(id='k1', label=T('Receiving goods from suppliers into distribution', '把供应商的货收进配送体系'), zone='in', why=T('Goods in.', '货进来。')),
        dict(id='k2', label=T('Running stores and the shelves in them', '运营门店和货架'), zone='ops', why=T('Turning inputs into the offer shoppers see.', '把投入变成购物者看到的产品。')),
        dict(id='k3', label=T('Same-day delivery from fulfilment centres', '从履约中心当日送达'), zone='out', why=T('Getting the offer to the customer.', '把产品送到顾客手上。')),
        dict(id='k4', label=T('Flybuys offers to members', '给会员的 Flybuys 优惠'), zone='mkt', why=T('Promotion and selling.', '促销与销售。')),
        dict(id='k5', label=T('Help for a shopper with a wrong item', '帮拿错货的购物者处理问题'), zone='svc', why=T('After-sale support.', '售后支持。')),
        dict(id='k6', label=T('Training team members and measuring their engagement', '培训员工并测量他们的敬业度'), zone='sup', why=T('Human resource management supports every primary activity.', '人力资源管理支撑每一项主要活动。')),
    ]
    fw_zones = [dict(id='por', label=T('Porter: how to compete (cost or difference, broad or narrow)', 'Porter：怎么竞争（成本还是差异，宽还是窄）')),
                dict(id='ans', label=T('Ansoff: where to grow (products and markets)', 'Ansoff：往哪里增长（产品与市场）')),
                dict(id='dis', label=T('Value disciplines: how to be best (what to excel at)', '价值准则：怎样做到最强（擅长什么）'))]
    fw_chips = [
        dict(id='f1', label=T('Lowest cost in a broad market', '宽市场里的最低成本'), zone='por', why=T('Cost leadership.', '成本领先。')),
        dict(id='f2', label=T('Stuck in the middle', '夹在中间'), zone='por', why=T('Neither cheapest nor different: a Porter outcome.', '既不最便宜也不独特：Porter 的一种结果。')),
        dict(id='f3', label=T('Sell the current product to new markets', '把现有产品卖到新市场'), zone='ans', why=T('Market development.', '市场开发。')),
        dict(id='f4', label=T('New products for new markets', '新产品卖给新市场'), zone='ans', why=T('Diversification.', '多元化。')),
        dict(id='f5', label=T('Sell more of the same to the same buyers', '向同样的买家多卖同样的东西'), zone='ans', why=T('Market penetration.', '市场渗透。')),
        dict(id='f6', label=T('Excel at the lifetime value of each customer', '把每个顾客的终身价值做到最好'), zone='dis', why=T('Customer intimacy.', '客户亲密。')),
        dict(id='f7', label=T('Lead on process and cost across the business', '在整个业务的流程和成本上领先'), zone='dis', why=T('Operational excellence.', '卓越运营。')),
        dict(id='f8', label=T('Always first with new, innovative offers', '总是第一个推出新颖、创新的产品'), zone='dis', why=T('Product leadership.', '产品领先。')),
    ]
    return dict(
        id=f'{CID}-advantage',
        title=T('Why can this firm do what others cannot, and for how long?', '为什么这家企业能做到别人做不到的，能维持多久？'),
        description=T('Core competence and the four tests, the value chain, and the three frameworks that are easy to mix up (Porter, Ansoff, value disciplines), with Hilton and Coles.',
                      '核心能力与四项检验、价值链，以及三个容易混的框架（Porter、Ansoff、价值准则），案例是 Hilton 和 Coles。'),
        minutes=45,
        skills=[{'id': SK, 'name': T('Explaining and applying competitive advantage frameworks', '解释并应用竞争优势框架')}],
        misconceptions=[
            {'id': 'resource-is-competence', 'description': T('any valuable resource is a core competence', '任何有价值的资源都是核心能力')},
            {'id': 'mix-frameworks', 'description': T('Porter, Ansoff and the value disciplines answer the same question', 'Porter、Ansoff 和价值准则回答的是同一个问题')},
        ],
        steps=[
            read('puzzle', T('A feature a rival ships in a month', '对手一个月就能做出来的功能'),
                 p(T("A hotel chain launches an app feature, or a supermarket launches same-day delivery. Within a year, the rivals have it too. Yet Hilton’s guests keep earning points in a programme with 243 million members, and nobody has copied that.",
                     "一家酒店集团上线一个应用功能，或一家超市推出当日送达。一年之内，对手都有了。可是 Hilton 的客人仍在一个有 2.43 亿会员的计划里累积积分，没有人复制得了。")),
                 p(T("What is the difference between the thing that can be copied in a month and the thing that cannot?", "能一个月复制的东西，和复制不了的东西，区别在哪？")), chapter=CH['puzzle']),
            predict('guess', SK, T("What makes an advantage last?", "什么让优势持久？"),
                    [(T("Being valuable, rare, and hard to copy or replace", "有价值、稀缺，而且难模仿、难替代"), True),
                     (T("Being the first to launch it", "第一个推出"), T("First movers are copied quickly if the thing is easy to imitate.", "如果东西容易模仿，先行者很快就被追上。")),
                     (T("Having the largest marketing budget", "营销预算最大"), T("Budgets can be matched; an accumulated network cannot.", "预算能被追平；长期积累的网络不能。")),
                     (T("Being the cheapest", "最便宜"), T("Cost advantages can be copied unless they rest on something deeper.", "成本优势除非建立在更深的东西上，否则会被复制。"))],
                    T("Those four tests (valuable, rare, costly to imitate, non-substitutable: **VRIN**) are the exam’s test of a **core competence**. Apply them to what Hilton and Coles have.", "这四项检验（有价值、稀缺、难模仿、难替代：**VRIN**）就是考试里检验**核心能力**的标准。用它们去检验 Hilton 和 Coles 拥有的东西。")),
            read('touch', T('Core competence or just a resource?', '核心能力，还是只是资源？'),
                 p(T("Six things Hilton and Coles have or do. Only some of them would survive the four tests.", "Hilton 和 Coles 拥有或做的六件事。只有一部分经得起四项检验。")),
                 tag(T('Six resources and activities of Hilton and Coles to tag as core competence or easy to copy.', 'Hilton 和 Coles 的六项资源与活动，标为核心能力或易被模仿。'), cats, items,
                     done=T("A **resource** (a thing: an app feature, a price) is easy to buy. A **capability** (a team’s skill at using resources) and a **core competence** (a bundle of capabilities that passes VRIN) are what rivals cannot buy.", "**资源**（一个东西：应用功能、价格）容易买到。**能力**（团队运用资源的技能）和**核心能力**（通过 VRIN 的能力组合）才是对手买不到的。"), height=720),
                 chapter=CH['touch']),
            read('touch2', T('Where in the chain', '链条的哪一环'),
                 p(T("Porter’s value chain splits a firm into the activities that make and deliver the product and those that support them. Place six things Coles does.", "Porter 的价值链把企业拆成制造交付产品的活动，和支撑这些活动的活动。把 Coles 做的六件事放进去。")),
                 place(T('Six Coles activities to place on the value chain: inbound logistics, operations, outbound logistics, marketing and sales, service, support.', 'Coles 的六项活动，放到价值链上：进货物流、运营、出货物流、营销销售、服务、支持活动。'), chain_zones, chain_chips, cols=3,
                       done=T("Advantage comes from doing one of these **cheaper** (cost advantage) or **differently** (differentiation) than rivals do. The same chain, drawn for insurance or banking, has different boxes: draw it for the industry in the question.", "优势来自把其中某一环做得比对手**更便宜**（成本优势）或**更不同**（差异化）。同一条链画到保险或银行，格子就不同：要按题目里的行业来画。"), height=820)),
            read('touch3', T('Three frameworks, three questions', '三个框架，三个问题'),
                 p(T("Porter, Ansoff and Treacy and Wiersema are three different frameworks that students mix up. Sort the phrases by the question each answers.", "Porter、Ansoff、Treacy 和 Wiersema 是三个不同的框架，学生常常混。按各自回答的问题把这些说法分类。")),
                 place(T('Eight phrases to place under Porter, Ansoff or the value disciplines.', '八个说法，放到 Porter、Ansoff 或价值准则下。'), fw_zones, fw_chips, cols=3,
                       done=T("**Porter**: how do we compete? **Ansoff**: where do we grow? **Value disciplines**: what do we excel at? Name the right framework for the question first, and half of the Explain part is done.", "**Porter**：怎么竞争？**Ansoff**：往哪里增长？**价值准则**：擅长什么？先把题目对应的框架认对，“解释”部分就完成一半。"), height=860)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 h(T('Marketing’s contribution moved through three eras (Lusch and Webster)', '营销的贡献经历了三个时代（Lusch 和 Webster）')),
                 table([T('Era', '时代'), T('Marketing as', '营销是'), T('Value sits in', '价值在于'), T('Metaphor', '隐喻')],
                       [T('1', '1'), T('utility creating and value adding', '创造效用、增加价值'), T('exchange', '交换'), T('machine', '机器')],
                       [T('2', '2'), T('customer-oriented and value proposing', '以顾客为导向、提出价值主张'), T('use', '使用'), T('organisation', '组织')],
                       [T('3', '3'), T('stakeholder-unifying and value co-creating', '统合利益相关者、共同创造价值'), T('context', '情境'), T('network', '网络')]),
                 p(T("Marketing moves from a **physical process sequence** (make, sell the product; cost-plus price) to a **value delivery sequence**: choose the value, provide the value, communicate the value.", "营销从**物理流程顺序**（制造、卖产品；成本加成定价）转向**价值交付顺序**：选择价值、提供价值、沟通价值。")),
                 h(T('Competitive advantage', '竞争优势')),
                 ul(T("**Resources** (tangible and intangible) combine into **capabilities** (teams of resources); those that are **valuable, rare, costly to imitate and non-substitutable** are **core competences** (Prahalad and Hamel). A new AI assistant handling two-thirds of a firm’s service chats in a month, as Klarna reported, is a capability in the making.", "**资源**（有形和无形）组合成**能力**（资源的团队）；其中**有价值、稀缺、难模仿、难替代**的是**核心能力**（Prahalad 和 Hamel）。Klarna 报告的 AI 助手一个月内承担了三分之二的客服对话，就是一个正在形成的能力。"),
                    T("**Value chain** (Porter): primary activities (inbound logistics, operations, outbound logistics, marketing and sales, service) and support activities (infrastructure, HR, technology, procurement); advantage from lower cost or differentiation.", "**价值链**（Porter）：主要活动（进货物流、运营、出货物流、营销销售、服务）和支持活动（基础设施、人力、技术、采购）；优势来自更低成本或差异化。"),
                    T("**Generic strategies** (Porter): cost leadership, differentiation, each broad or focused; “stuck in the middle” is neither.", "**通用战略**（Porter）：成本领先、差异化，各分宽与聚焦；“夹在中间”则两者都不是。"),
                    T("**Product-market growth** (Ansoff): market penetration, market development, product development, diversification.", "**产品–市场增长**（Ansoff）：市场渗透、市场开发、产品开发、多元化。"),
                    T("**Value disciplines** (Treacy and Wiersema): operational excellence (process, cost, price), customer intimacy (lifetime value), product leadership (new, innovative). Excel at one, match competitors on the other two; mastering one takes years.", "**价值准则**（Treacy 和 Wiersema）：卓越运营（流程、成本、价格）、客户亲密（终身价值）、产品领先（新颖、创新）。在一项上出众，另两项与对手持平；做精一项要花多年。")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Take Hilton’s Honors programme (243 million members at 31 December 2025) and test it against the four tests in four sentences, one per test, with a because for at least two.", "拿 Hilton 的 Honors 计划（截至 2025 年 12 月 31 日有 2.43 亿会员），用四项检验各写一句，至少两句带“因为”。"),
                    [T("Valuable: members get benefits (points and money, member discount, free standard Wi-Fi) and Hilton gets direct bookings", "有价值：会员得到好处（积分加现金、会员折扣、免费标准 Wi-Fi），Hilton 得到直接预订"),
                     T("Rare and costly to imitate because of the scale and years of members, with the numbers right", "稀缺且难模仿，因为会员规模和积累的年数，数字没错"),
                     T("Non-substitutable or its limits: others can run programmes, so the competence is the network of members and partners", "难替代或其局限：别人也能做计划，所以能力是会员和合作伙伴的网络"),
                     T("Says this is a reading of the competence, not Hilton’s own claim", "说明这是对能力的解读，不是 Hilton 自己的说法")],
                    T("Valuable: members get a points-and-money option, a member discount and free standard Wi-Fi, and Hilton gets bookings through its own channels, and the programme grew 15% in the year to December 2025. Rare: 243 million members cannot be bought, so a rival would need years, which makes it costly to imitate. Substitutable? Rivals run programmes, so Honors is not unique as a type; the competence is the scale of the member base and the partners such as card providers who fund it. This is my reading of what makes it a competence, not Hilton’s claim.",
                      "有价值：会员得到积分加现金选项、会员折扣和免费标准 Wi-Fi，Hilton 通过自己的渠道得到预订，该计划在截至 2025 年 12 月的一年里增长了 15%。稀缺：2.43 亿会员买不到，对手要花多年，所以难模仿。可替代吗？对手也有计划，所以 Honors 作为类型并不独特；能力在于会员基数的规模，以及为它出资的信用卡等合作伙伴。这是我对其为何构成能力的解读，不是 Hilton 的说法。"),
                    T("Name the test, give the fact, say because.", "点出检验，给事实，说“因为”。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("A firm plans to sell its existing hotel brand in a new country. Which framework names that move?", "一家企业打算把现有酒店品牌带到新国家。哪个框架命名这个动作？"),
                   [(T("Ansoff: market development (existing product, new market)", "Ansoff：市场开发（现有产品、新市场）"), True),
                    (T("Porter: differentiation", "Porter：差异化"), T("That is about how to compete, not where to grow.", "那是关于怎么竞争，而不是往哪增长。")),
                    (T("Value discipline: product leadership", "价值准则：产品领先"), T("Product leadership is about what you excel at, not the market entered.", "产品领先说的是擅长什么，不是进入哪个市场。"))],
                   T("Read the question the framework answers.", "看清框架回答的问题。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 3: in service-dominant logic, the unit of analysis is the…", "来自第 3 课：服务主导逻辑里，分析单位是……"),
                   [(T("relationship between firm and customer", "企业与顾客之间的关系"), True), (T("product output", "产品产出"), T("That is goods logic.", "那是商品逻辑。"))], T("Relationship.", "关系。"), first=True),
            recall('r2', SK, T("From lesson 2: a firm that works with lead users years ahead of the market is…", "来自第 2 课：和领先市场多年的先锋用户合作的企业是……"),
                   [(T("market-oriented", "市场导向"), True), (T("customer-led", "顾客牵着走"), T("Customer-led firms follow what is said now.", "顾客牵着走的企业跟随现在说的话。"))], T("Lead users are the proactive learning route.", "先锋用户是主动学习的途径。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain core competence and the criteria for it. (b) Apply the idea to Hilton Hotels in Australia. (c) Make two recommendations.", "题目。(a) 解释核心能力及其判断标准。(b) 把这个概念应用到澳大利亚的 Hilton 酒店。(c) 给出两条建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("Resources combine into capabilities, and a competence is a capability", "资源组合成能力，核心能力是一种能力"), T("The four criteria: valuable, rare, costly to imitate, non-substitutable", "四个标准：有价值、稀缺、难模仿、难替代"),
                         T("Why it matters: it sustains advantage, because rivals cannot buy it", "为什么重要：能维持优势，因为对手买不到"), T("Precise terms (Prahalad and Hamel) and an example", "用词精确（Prahalad 和 Hamel）并有例子")],
                        T("A core competence (Prahalad and Hamel) is a bundle of capabilities, built from tangible and intangible resources, that gives a firm a lasting advantage. It must be valuable to customers, rare, costly for rivals to imitate and non-substitutable. A resource such as a price or app feature can be bought, so it gives only temporary advantage; a competence rests on accumulated skills and relationships, so rivals cannot simply acquire it. Managers identify competences through value chain analysis.",
                          "核心能力（Prahalad 和 Hamel）是由有形和无形资源构成的一组能力，给企业带来持久优势。它必须对顾客有价值、稀缺、对手难以模仿、不可替代。价格或应用功能这类资源可以买到，所以只带来暂时的优势；能力建立在积累的技能和关系之上，对手无法直接获得。管理者通过价值链分析识别能力。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Names a Hilton competence: for example franchise brand system, Honors, standards across hotels", "指出一项 Hilton 的能力：如特许品牌体系、Honors、跨酒店的标准"),
                         T("Uses verified facts: 243 million Honors members, about 8,239 franchised against 873 managed and 46 owned", "用已核实的事实：2.43 亿 Honors 会员，约 8,239 家特许对 873 家受托管理和 46 家自有"),
                         T("Tests it on the criteria with cause and effect", "按标准检验并说清因果"), T("Shows the limits or what a rival could copy", "说明局限或对手可能模仿什么")],
                        T("Hilton’s competence is running a global brand through other people’s hotels. At the end of 2025 about 8,239 properties were franchised against 873 managed and 46 owned, so its advantage cannot rest on owning buildings. It rests on the brand and the standards and systems that make a franchised stay feel the same, and on Honors with 243 million members, which sends direct bookings to those hotels. Valuable: owners get demand and guests get consistency. Rare and costly to imitate: building a member base of that size and a trusted standard takes years, so a new chain cannot buy it. The weak point is substitutability: guests could be won by another well-known brand or a rental platform, and a franchisee’s lapse harms the brand, so the competence must be protected by standards and audits.",
                          "Hilton 的能力是通过别人的酒店来运营一个全球品牌。2025 年底，约 8,239 家物业是特许经营，873 家受托管理，46 家自有，所以它的优势不能靠拥有建筑。它靠的是品牌，以及让特许酒店的住宿感觉一致的标准和体系，还有拥有 2.43 亿会员的 Honors，把直接预订送给这些酒店。有价值：业主得到需求，客人得到一致性。稀缺且难模仿：建立这么大的会员基础和被信任的标准要花多年，新连锁买不来。薄弱点在可替代性：客人可能被另一个知名品牌或租赁平台争走，加盟商的疏漏也会伤害品牌，所以能力必须靠标准和审核来保护。")),
                       (T("Write the **Recommend** part: exactly two.", "写**建议**部分：恰好两条。"),
                        [T("Exactly two that follow from the analysis (protect standards in franchised hotels; deepen Honors)", "恰好两条，从分析里推出（保护特许酒店的标准；深化 Honors）"),
                         T("Each actionable", "每条可执行"), T("A risk named", "点出风险")],
                        T("First, tie franchise renewals to audited service standards and Honors guest scores, because the competence depends on every franchised hotel delivering the same stay. The risk is owner resistance, so pair audits with training support. Second, give Honors members benefits that only the member base can fund, such as partner offers with card providers, because partners are already part of how the programme is paid for. The risk is that the benefits dilute the brand if offers cheapen it, so keep them tied to stays.",
                          "第一，把特许续约和经审核的服务标准、Honors 客人评分挂钩，因为能力取决于每家特许酒店都交付同样的住宿体验。风险是业主抵触，所以审核要配上培训支持。第二，给 Honors 会员只有庞大会员基础才能支撑的福利，例如与信用卡机构合作的优惠，因为合作伙伴已经是该计划资金来源的一部分。风险是优惠做得廉价会稀释品牌，所以福利要与住宿挂钩。")),
                       ),
    )
